-- 011_manual_grading: immutable per-item review events and the narrow grading permission/menu.

-- @step create_exam_review_event
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_review_event' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_review_event') = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_review_event' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('exam_record_id','record_question_id','reviewer_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'before_score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'after_score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('before_comment','after_comment') AND DATA_TYPE = 'text' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'grading_version' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)'))) = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_review_event') = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_review_event' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_exam_review_event_version' AND NON_UNIQUE = 0 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'exam_record_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'record_question_id') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'grading_version')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_exam_review_event_record_created' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'exam_record_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'created_at')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `exam_review_event` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `exam_record_id` BIGINT UNSIGNED NOT NULL, `record_question_id` BIGINT UNSIGNED NOT NULL, `reviewer_id` BIGINT UNSIGNED NOT NULL, `before_score` DECIMAL(5,2) NULL, `after_score` DECIMAL(5,2) NOT NULL, `before_comment` TEXT NULL, `after_comment` TEXT NULL, `grading_version` INT UNSIGNED NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_exam_review_event_version` (`exam_record_id`,`record_question_id`,`grading_version`), KEY `idx_exam_review_event_record_created` (`exam_record_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='图片题逐次人工评分不可变审计';

-- @step register_exam_review_permission
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM `sys_permission` WHERE `code` = 'exam_records:review' AND `name` = '人工阅卷') = 1 THEN 1 ELSE 0 END AS complete;
INSERT IGNORE INTO `sys_permission` (`code`, `name`) SELECT 'exam_records:review', '人工阅卷' WHERE NOT EXISTS (SELECT 1 FROM `sys_permission` WHERE `code` = 'exam_records:review');

-- Existing valid label/icon/sort/status customizations are preserved. A row at
-- the same route with the wrong parent/type/permission leaves the probe false.
-- @step register_grading_menu
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM `sys_menu` WHERE `route_path` = '/admin/grading') = 1 AND (SELECT COUNT(*) FROM `sys_menu` WHERE `route_path` = '/admin/grading' AND `parent_id` = 1 AND `type` = 'menu' AND `permission_code` = 'exam_records:review') = 1 THEN 1 ELSE 0 END AS complete;
INSERT IGNORE INTO `sys_menu` (`parent_id`, `name`, `type`, `route_path`, `permission_code`, `icon`, `sort`, `status`) SELECT 1, '人工阅卷', 'menu', '/admin/grading', 'exam_records:review', 'EditPen', 37, 1 WHERE EXISTS (SELECT 1 FROM `sys_menu` WHERE `id` = 1 AND `type` = 'directory') AND NOT EXISTS (SELECT 1 FROM `sys_menu` WHERE `route_path` = '/admin/grading');
